            var launch=ReplayCustomWeaponFact.Launch(context,state.CustomWeapons!.Sequence+1,f.Launch());Check(ReplayCustomWeaponFact.TryRead(launch.CopyBytes(),context,out _),"authority context accepts actual fixture source certificate with exact same Start");state.Accept(launch.CopyBytes(),20);var contact=ReplayCustomWeaponFact.Contact(context,state.CustomWeapons!.Sequence+1,f.World,f.Contact());state.Accept(contact.CopyBytes(),21);Check(state.CustomWeapons.TryContact(f.Launch().Identity,out var outcome,out uint contactFrame)&&outcome==f.Contact()&&contactFrame==21,"authority context terminal retains genuine fixture certificate/outcome values");
